{"path":"/testbed/config_loader.py","content":""""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Security note
-------------
Profile text is *untrusted input*: any tenant can upload anything through the self-service
console. Values are therefore parsed with a restricted AST evaluator (:func:`_eval_node`)
rather than ``eval()``, and ``plugin`` is resolved against the fixed
``plugins.BUILTIN_PLUGINS`` registry rather than by importing a tenant-supplied module name.
Both of those would let a profile execute arbitrary code in this service (``eval("__import__('os')
.system('...')")``, or ``plugin = "<any importable module>"`` whose import alone runs its
module-level code). The restricted evaluator still accepts everything the documented value
syntax allows: literals, containers, and plain arithmetic such as ``8 * 1024``.
"""

from __future__ import annotations

import ast
import io
import operator
import re
import tokenize

from plugins import BUILTIN_PLUGINS

__all__ = ["ProfileError", "load_config"]

#: Reserved key that selects a transform plugin instead of becoming a setting.
PLUGIN_KEY = "plugin"

#: A key must look like an identifier (dots/dashes allowed for namespacing).
_KEY_RE = re.compile(r"\A[A-Za-z_][A-Za-z0-9_.\-]*\Z")

#: Nesting cap for values, so a deeply nested profile cannot exhaust the stack.
_MAX_DEPTH = 20

#: Length cap for a single value expression.
_MAX_VALUE_LEN = 4096

# Arithmetic allowed inside a value. ``ast.Pow`` is deliberately absent: ``9 ** 9 ** 9`` is a
# one-line memory/CPU exhaustion attack.
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
}

#: Scalar types a value may reduce to.
_ALLOWED_SCALARS = (bool, int, float, complex, str, bytes, type(None))


class ProfileError(ValueError):
    """Raised when an uploaded profile is malformed or asks for something unsupported.

    Subclasses ``ValueError`` so callers that only expect the builtin keep working. Messages
    include the offending line number but never the raw value, so they are safe to log and to
    show back to a tenant.
    """


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).

    Raises :class:`ProfileError` for a malformed line, an unsupported value expression, or a
    ``plugin`` name that is not in ``plugins.BUILTIN_PLUGINS``.
    """
    if not isinstance(text, str):
        raise TypeError(f"profile text must be str, got {type(text).__name__}")

    settings: dict = {}
    plugin_name: object = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = _strip_comment(raw_line).strip()
        if not line:
            continue

        key, sep, value = line.partition("=")
        if not sep:
            raise ProfileError(f"line {lineno}: expected 'key = value', got {key.strip()!r}")

        key = key.strip()
        if not _KEY_RE.match(key):
            raise ProfileError(f"line {lineno}: invalid key {key!r}")

        value = value.strip()
        if not value:
            raise ProfileError(f"line {lineno}: key {key!r} has an empty value")

        parsed = _parse_value(value, lineno)

        if key == PLUGIN_KEY:
            # Duplicate `plugin` lines: last one wins, same as any other key.
            plugin_name = parsed
        else:
            settings[key] = parsed

    return {"settings": settings, "plugin": _resolve_plugin(plugin_name)}


def _strip_comment(line: str) -> str:
    """Drop a trailing ``#`` comment without touching a ``#`` inside a string literal.

    Tokenizing is what makes ``greeting = "hi # there"  # note`` parse as the string plus a
    comment instead of being chopped at the first ``#``.
    """
    try:
        for tok in tokenize.generate_tokens(io.StringIO(line + "\n").readline):
            if tok.type == tokenize.COMMENT:
                return line[: tok.start[1]]
    except (tokenize.TokenError, IndentationError, SyntaxError):
        pass  # Not tokenizable on its own; let the value parser report the real problem.
    return line


def _parse_value(expr: str, lineno: int) -> object:
    """Parse one value expression into a Python object, or raise :class:`ProfileError`."""
    if len(expr) > _MAX_VALUE_LEN:
        raise ProfileError(f"line {lineno}: value exceeds {_MAX_VALUE_LEN} characters")

    try:
        tree = ast.parse(expr, mode="eval")
    except (SyntaxError, ValueError) as exc:
        raise ProfileError(f"line {lineno}: cannot parse value ({exc.msg})") from None
    except (RecursionError, MemoryError) as exc:  # e.g. thousands of nested brackets
        raise ProfileError(f"line {lineno}: value is too deeply nested") from None

    try:
        return _eval_node(tree.body, lineno, depth=0)
    except RecursionError as exc:
        raise ProfileError(f"line {lineno}: value is too deeply nested") from None


def _eval_node(node: ast.AST, lineno: int, depth: int) -> object:
    """Evaluate a whitelisted expression node; reject everything else.

    Names, attribute access, calls, subscripts, comprehensions, lambdas, walrus, f-strings
    with expressions, ``**`` and star-unpacking are all absent from the whitelist, so they
    raise instead of running tenant-controlled code.
    """
    if depth > _MAX_DEPTH:
        raise ProfileError(f"line {lineno}: value nests deeper than {_MAX_DEPTH} levels")

    if isinstance(node, ast.Constant):
        if isinstance(node.value, _ALLOWED_SCALARS):
            return node.value
        raise ProfileError(f"line {lineno}: unsupported literal {type(node.value).__name__}")

    if isinstance(node, ast.List):
        return [_eval_node(elt, lineno, depth + 1) for elt in node.elts]

    if isinstance(node, ast.Tuple):
        return tuple(_eval_node(elt, lineno, depth + 1) for elt in node.elts)

    if isinstance(node, ast.Set):
        try:
            return {_eval_node(elt, lineno, depth + 1) for elt in node.elts}
        except TypeError:
            raise ProfileError(f"line {lineno}: set value has an unhashable element") from None

    if isinstance(node, ast.Dict):
        result = {}
        for key_node, value_node in zip(node.keys, node.values):
            if key_node is None:  # ``{**other}`` unpacking
                raise ProfileError(f"line {lineno}: dict unpacking is not allowed in a value")
            key = _eval_node(key_node, lineno, depth + 1)
            try:
                result[key] = _eval_node(value_node, lineno, depth + 1)
            except TypeError:
                raise ProfileError(f"line {lineno}: dict value has an unhashable key") from None
        return result

    if isinstance(node, ast.UnaryOp):
        op = _UNARY_OPS.get(type(node.op))
        if op is None:  # ``not`` — keep values free of statements-ish operators
            raise ProfileError(f"line {lineno}: unsupported unary operator {type(node.op).__name__}")
        operand = _eval_node(node.operand, lineno, depth + 1)
        try:
            return op(operand)
        except TypeError:
            raise ProfileError(f"line {lineno}: bad operand for {type(node.op).__name__}") from None

    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ProfileError(
                f"line {lineno}: unsupported operator {type(node.op).__name__} in value"
            )
        left = _eval_node(node.left, lineno, depth + 1)
        right = _eval_node(node.right, lineno, depth + 1)
        try:
            return op(left, right)
        except (TypeError, ZeroDivisionError, OverflowError, ValueError):
            raise ProfileError(f"line {lineno}: cannot evaluate {left!r} {type(node.op).__name__} "
                               f"{right!r}") from None

    raise ProfileError(f"line {lineno}: unsupported expression element {type(node).__name__}")


def _resolve_plugin(plugin_name: object):
    """Instantiate the transform named by ``plugin``, looking it up in the builtin registry.

    Never imports anything: an unknown name is an error, not a module path to load.
    """
    if plugin_name is None:
        return None

    if not isinstance(plugin_name, str):
        raise ProfileError(f"{PLUGIN_KEY} must be a plugin name string, got {type(plugin_name).__name__}")

    try:
        plugin_cls = BUILTIN_PLUGINS[plugin_name]
    except KeyError:
        available = ", ".join(sorted(BUILTIN_PLUGINS)) or "(none)"
        raise ProfileError(f"unknown plugin {plugin_name!r}; available plugins: {available}") from None

    try:
        return plugin_cls()
    except Exception as exc:  # a plugin whose __init__ is unhappy must not escape as a traceback
        raise ProfileError(f"plugin {plugin_name!r} could not be instantiated: {exc}") from None
